acceptance_cmd:
set -eu
T=APP-20260808-4d0dbb
have_static=0
./ops/backlog.py show "$T" --json | grep -Fq 'acceptance_cmd_static' && have_static=1
./ops/backlog.py verify --help 2>&1 | grep -Fq -- '--static-only' && have_static=1
test "$have_static" = "1" || { echo "FAIL: no way to express or run the static subset of an acceptance criterion"; exit 1; }
start=$(date +%s)
if ./ops/backlog.py verify "$T" --static-only >/dev/null 2>&1 || ./ops/backlog.py show "$T" --json | uv run --no-project --python 3.13 python -c 'import json,subprocess,sys; c=json.load(sys.stdin)["entry"].get("acceptance_cmd_static"); sys.exit(1 if not c else subprocess.run(["bash","-c",c]).returncode)'; then :; else echo "FAIL: the static path did not return 0 for $T"; exit 1; fi
end=$(date +%s)
test $((end-start)) -lt 60 || { echo "FAIL: the static path took $((end-start))s — it is still pulling in a toolchain"; exit 1; }
grep -rEq 'static.only|acceptance_cmd_static' ops/tests/ || { echo "FAIL: no test pins that anchor still gates on the FULL criterion"; exit 1; }
echo OK
